/*!
 * Casinocademy client-side search
 *
 * Fetches the static index (search.json, generated by Jekyll) once, then filters
 * it in the browser. No dependencies.
 *
 * Markup contract (see _includes/header.html):
 *   <form data-search data-search-index="/search.json">
 *     <input type="text" name="query">
 *   </form>
 * A results panel is created for each form. By default it is inserted right after the form;
 * with data-search-mount="floating" it is attached to <body> and positioned under the input
 * (needed in the header, where theme CSS styles every li/a inside the nav).
 *
 * Structure of this file:
 *   1. CONFIG        tunable constants
 *   2. Text helpers  tokenizing, escaping, highlighting
 *   3. SearchIndex   loading the JSON and ranking documents
 *   4. SearchBox     UI behaviour for one form (events, rendering, keyboard, ARIA)
 *   5. Bootstrap     wires up every [data-search] form
 */
(function () {
	'use strict';

	/* ------------------------------------------------------------------ */
	/* 1. CONFIG                                                           */
	/* ------------------------------------------------------------------ */

	var CONFIG = {
		minChars: 2,          // do not search for anything shorter than this
		maxResults: 8,        // results shown in the panel
		snippetLength: 140,   // characters of body text shown around a match
		debounceMs: 120,      // wait after typing stops before searching
		bodyHitCap: 5,        // a word repeated in the body stops adding score after this many hits
		weights: { title: 10, titleStarts: 5, subtitle: 4, author: 3, body: 1 }
	};

	/* ------------------------------------------------------------------ */
	/* 2. Text helpers                                                     */
	/* ------------------------------------------------------------------ */

	function tokenize(text) {
		return String(text || '')
			.toLowerCase()
			.split(/[^\wÀ-ɏ]+/)
			.filter(function (t) { return t.length > 0; });
	}

	function escapeHtml(text) {
		return String(text).replace(/[&<>"']/g, function (c) {
			return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
		});
	}

	function escapeRegExp(text) {
		return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	}

	// Returns HTML: the text escaped, with every search term wrapped in <mark> where it starts a word.
	// Escaping happens per segment so a term such as "amp" can never match inside an entity.
	// (Group 1 is the character before the word, so no lookbehind is needed for older Safari.)
	function highlight(text, terms) {
		if (!terms.length) { return escapeHtml(text); }
		var re = new RegExp('(^|[^\\w\\u00c0-\\u024f])(' + terms.map(escapeRegExp).join('|') + ')', 'gi');
		var out = '', last = 0, m;
		while ((m = re.exec(text)) !== null) {
			var markStart = m.index + m[1].length;
			out += escapeHtml(text.slice(last, markStart)) + '<mark>' + escapeHtml(m[2]) + '</mark>';
			last = markStart + m[2].length;
			re.lastIndex = last;          // the next match may reuse the character right after this one
		}
		return out + escapeHtml(text.slice(last));
	}

	var WORD_CHAR = /[\w\u00c0-\u024f]/;

	// Position of `term` where it begins a word ("ace" matches "Ace of Games", not "Facebook"), or -1.
	function indexOfWord(haystack, term, from) {
		var at = haystack.indexOf(term, from || 0);
		while (at > 0 && WORD_CHAR.test(haystack.charAt(at - 1))) {
			at = haystack.indexOf(term, at + 1);
		}
		return at;
	}

	function countOccurrences(haystack, needle, cap) {
		var count = 0, from = 0, at;
		while (count < cap && (at = indexOfWord(haystack, needle, from)) !== -1) {
			count++;
			from = at + needle.length;
		}
		return count;
	}

	// A plain-text excerpt of `body` around the first place a term appears.
	function makeSnippet(doc, terms) {
		var body = doc.body || '';
		var lower = doc._body;
		var at = -1;
		for (var i = 0; i < terms.length && at === -1; i++) {
			at = indexOfWord(lower, terms[i]);
		}
		if (at === -1) { return doc.subtitle || body.slice(0, CONFIG.snippetLength); }

		var start = Math.max(0, at - Math.floor(CONFIG.snippetLength / 3));
		var end = Math.min(body.length, start + CONFIG.snippetLength);
		if (start > 0) { start = body.indexOf(' ', start) + 1 || start; }  // begin on a word boundary
		return (start > 0 ? '…' : '') + body.slice(start, end).trim() + (end < body.length ? '…' : '');
	}

	/* ------------------------------------------------------------------ */
	/* 3. SearchIndex                                                      */
	/* ------------------------------------------------------------------ */

	var indexCache = {};  // url -> Promise<Array<doc>>

	function loadIndex(url) {
		if (!indexCache[url]) {
			indexCache[url] = fetch(url, { credentials: 'same-origin' })
				.then(function (response) {
					if (!response.ok) { throw new Error('HTTP ' + response.status); }
					return response.json();
				})
				.then(function (docs) {
					docs.forEach(function (doc) {   // lowercase once, reuse on every keystroke
						doc._title = (doc.title || '').toLowerCase();
						doc._subtitle = (doc.subtitle || '').toLowerCase();
						doc._author = (doc.author || '').toLowerCase();
						doc._body = (doc.body || '').toLowerCase();
					});
					return docs;
				})
				.catch(function (error) {
					delete indexCache[url];         // allow a retry on the next keystroke
					throw error;
				});
		}
		return indexCache[url];
	}

	// Every term must start a word somewhere (AND). Returns 0 when any term is missing.
	function scoreDoc(doc, terms) {
		var w = CONFIG.weights, total = 0;
		for (var i = 0; i < terms.length; i++) {
			var t = terms[i], termScore = 0, at;

			if ((at = indexOfWord(doc._title, t)) !== -1) {
				termScore += w.title;
				if (at === 0) { termScore += w.titleStarts; }
			}
			if (indexOfWord(doc._subtitle, t) !== -1) { termScore += w.subtitle; }
			if (indexOfWord(doc._author, t) !== -1) { termScore += w.author; }
			termScore += countOccurrences(doc._body, t, CONFIG.bodyHitCap) * w.body;

			if (termScore === 0) { return 0; }
			total += termScore;
		}
		return total;
	}

	function rank(docs, terms) {
		return docs
			.map(function (doc, position) { return { doc: doc, score: scoreDoc(doc, terms), position: position }; })
			.filter(function (r) { return r.score > 0; })
			.sort(function (a, b) { return b.score - a.score || a.position - b.position; })  // ties keep newest-first order
			.slice(0, CONFIG.maxResults)
			.map(function (r) { return r.doc; });
	}

	/* ------------------------------------------------------------------ */
	/* 4. SearchBox                                                        */
	/* ------------------------------------------------------------------ */

	var boxCount = 0;

	function SearchBox(form) {
		this.form = form;
		this.input = form.querySelector('input');
		this.indexUrl = form.getAttribute('data-search-index');
		if (!this.input || !this.indexUrl || !window.fetch) { return; }

		this.id = 'search-results-' + (++boxCount);
		this.results = [];
		this.active = -1;
		this.timer = null;
		this.requestId = 0;

		this.panel = document.createElement('div');
		this.panel.className = 'search-results';
		this.panel.id = this.id;
		this.panel.hidden = true;
		this.floating = form.getAttribute('data-search-mount') === 'floating';
		if (this.floating) {
			this.panel.classList.add('is-floating');
			document.body.appendChild(this.panel);
		} else {
			form.parentNode.insertBefore(this.panel, form.nextSibling);
		}

		this.input.setAttribute('role', 'combobox');
		this.input.setAttribute('aria-autocomplete', 'list');
		this.input.setAttribute('aria-controls', this.id);
		this.input.setAttribute('aria-expanded', 'false');

		this.bind();
	}

	SearchBox.prototype.bind = function () {
		var self = this;

		this.input.addEventListener('focus', function () {
			loadIndex(self.indexUrl).catch(function () {});   // warm the cache
			if (self.input.value.trim()) { self.update(); }
		});
		this.input.addEventListener('input', function () {
			clearTimeout(self.timer);
			self.timer = setTimeout(function () { self.update(); }, CONFIG.debounceMs);
		});
		this.input.addEventListener('keydown', function (event) { self.onKeydown(event); });

		this.form.addEventListener('submit', function (event) {
			event.preventDefault();
			self.openResult(self.active >= 0 ? self.active : 0);
		});
		this.form.addEventListener('reset', function () {
			setTimeout(function () { self.close(); }, 0);
		});

		// Keep focus in the input when a result is clicked, so the page's own
		// blur handlers (header search collapses on blur) do not hide the panel first.
		this.panel.addEventListener('mousedown', function (event) { event.preventDefault(); });

		// Close when focus leaves both the form and the panel (keyboard users tabbing away).
		var closeIfOutside = function () {
			setTimeout(function () {
				var el = document.activeElement;
				if (!self.form.contains(el) && !self.panel.contains(el)) { self.close(); }
			}, 0);
		};
		this.form.addEventListener('focusout', closeIfOutside);
		this.panel.addEventListener('focusout', closeIfOutside);

		if (this.floating) {
			var reposition = function () { if (!self.panel.hidden) { self.position(); } };
			window.addEventListener('resize', reposition);
			window.addEventListener('scroll', reposition, { passive: true });
		}

		document.addEventListener('click', function (event) {
			if (!self.form.contains(event.target) && !self.panel.contains(event.target)) { self.close(); }
		});
	};

	SearchBox.prototype.onKeydown = function (event) {
		switch (event.key) {
			case 'ArrowDown':
				if (this.results.length) { event.preventDefault(); this.setActive((this.active + 1) % this.results.length); }
				break;
			case 'ArrowUp':
				if (this.results.length) { event.preventDefault(); this.setActive((this.active - 1 + this.results.length) % this.results.length); }
				break;
			case 'Escape':
				if (!this.panel.hidden) { this.close(); }
				break;
		}
	};

	SearchBox.prototype.update = function () {
		var self = this;
		var query = this.input.value.trim();
		var terms = tokenize(query);
		var requestId = ++this.requestId;   // ignore responses that arrive after a newer keystroke

		if (query.length < CONFIG.minChars || !terms.length) { this.close(); return; }

		loadIndex(this.indexUrl).then(function (docs) {
			if (requestId !== self.requestId) { return; }
			self.results = rank(docs, terms);
			self.render(query, terms);
		}).catch(function () {
			if (requestId !== self.requestId) { return; }
			self.results = [];
			self.showMessage('Search is unavailable right now. Please try again later.');
		});
	};

	SearchBox.prototype.render = function (query, terms) {
		if (!this.results.length) {
			this.showMessage('No results for “' + escapeHtml(query) + '”.');
			return;
		}

		var self = this;
		var items = this.results.map(function (doc, i) {
			var meta = [doc.type === 'Page' ? 'Page' : doc.date, doc.author].filter(Boolean).join(' · ');
			return '<li role="option" id="' + self.id + '-opt-' + i + '" aria-selected="false">' +
				'<a href="' + escapeHtml(doc.url) + '" tabindex="-1">' +
				'<span class="search-result-title">' + highlight(doc.title, terms) + '</span>' +
				(meta ? '<span class="search-result-meta">' + escapeHtml(meta) + '</span>' : '') +
				'<span class="search-result-snippet">' + highlight(makeSnippet(doc, terms), terms) + '</span>' +
				'</a></li>';
		}).join('');

		this.panel.innerHTML = '<ul role="listbox" aria-label="Search results">' + items + '</ul>';
		this.active = -1;
		this.open();
	};

	SearchBox.prototype.showMessage = function (html) {
		this.panel.innerHTML = '<p class="search-message" role="status">' + html + '</p>';
		this.active = -1;
		this.open();
	};

	SearchBox.prototype.setActive = function (index) {
		var options = this.panel.querySelectorAll('[role="option"]');
		for (var i = 0; i < options.length; i++) {
			var on = (i === index);
			options[i].classList.toggle('is-active', on);
			options[i].setAttribute('aria-selected', on ? 'true' : 'false');
			if (on) {
				this.input.setAttribute('aria-activedescendant', options[i].id);
				if (options[i].scrollIntoView) { options[i].scrollIntoView({ block: 'nearest' }); }
			}
		}
		this.active = index;
	};

	SearchBox.prototype.openResult = function (index) {
		var doc = this.results[index];
		if (doc) { window.location.href = doc.url; }
	};

	// Floating panels sit just under the input, right-aligned with it (header is position: fixed).
	SearchBox.prototype.position = function () {
		var rect = this.input.getBoundingClientRect();
		this.panel.style.top = Math.round(rect.bottom + 6) + 'px';
		this.panel.style.right = Math.max(8, Math.round(document.documentElement.clientWidth - rect.right)) + 'px';
	};

	SearchBox.prototype.open = function () {
		this.panel.hidden = false;
		if (this.floating) { this.position(); }
		this.input.setAttribute('aria-expanded', 'true');
	};

	SearchBox.prototype.close = function () {
		clearTimeout(this.timer);
		this.requestId++;               // cancel any search still in flight
		this.panel.hidden = true;
		this.panel.innerHTML = '';
		this.results = [];
		this.active = -1;
		this.input.setAttribute('aria-expanded', 'false');
		this.input.removeAttribute('aria-activedescendant');
	};

	/* ------------------------------------------------------------------ */
	/* 5. Bootstrap                                                        */
	/* ------------------------------------------------------------------ */

	function init() {
		var forms = document.querySelectorAll('form[data-search]');
		for (var i = 0; i < forms.length; i++) { new SearchBox(forms[i]); }
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})();
